mapper.select:
SELECT DISTINCT TRIM(detail.id_card_no)
FROM employee_channel_bill_detail detail
INNER JOIN employee_channel_bill bill
        ON bill.id = detail.channel_bill_id
       AND bill.deleted = 1
WHERE bill.enterprise_id = #{enterpriseId}
  AND bill.channel_id = #{channelId}
  AND bill.settle_month = #{settleMonth}
  AND bill.bill_type != #{billType}
  AND detail.deleted = 1
